    srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0xd7b64) M (seg_rom RSEGS)) model)
               (t_emit (W 2 (msg_cannot_open path)) (t_exit (exit_code 2) (m_fs model))).
